构建失败（exit 101）多半是因为在 `thread::spawn` 的闭包里，`move` 绑定的变量 `a`、`b` 把同名的 worker 函数 `a`、`b` 遮住了，于是 `a(a, …)` / `b(a, …)` 会被当成在调用 `Arc`，无法通过编译。spawn 时把锁克隆到 `la`/`lb`（或其它不与函数名冲突的名字）再调用 `a(...)` / `b(...)` 即可。

握手与加锁顺序（先 `sa`/`a` 再 `sb`/`b`，与 `b` 对称）满足 R4–R5；bystander 只用 `flag`，不挡 worker（R6–R9）；主线程 `join` 两个 worker 后打印 `DONE a=1 b=1`（R11–R12）。

```rust
use concir_sync::Semaphore;
use std::sync::{Arc, Mutex};
use std::thread;

fn a(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    va: Arc<Mutex<u32>>,
) {
    let p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    p_sa.release();
    let _p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    *va.lock().unwrap() = 1;
}

fn b(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    vb: Arc<Mutex<u32>>,
) {
    let p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    p_sb.release();
    let _p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    *vb.lock().unwrap() = 1;
}

fn bystander(flag: Arc<Mutex<u64>>) {
    loop {
        if let Ok(mut f) = flag.try_lock() {
            *f = f.wrapping_add(1);
        }
    }
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let sa = Semaphore::new(1);
    let sb = Semaphore::new(1);
    let flag = Arc::new(Mutex::new(0u64));
    let va = Arc::new(Mutex::new(0u32));
    let vb = Arc::new(Mutex::new(0u32));

    let ha = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let va = Arc::clone(&va);
        thread::spawn(move || {
            a(a, b, sa, sb, va);
        })
    };
    let hb = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let vb = Arc::clone(&vb);
        thread::spawn(move || {
            b(a, b, sa, sb, vb);
        })
    };
    let _hbyst = {
        let flag = Arc::clone(&flag);
        thread::spawn(move || bystander(flag))
    };

    ha.join().unwrap();
    hb.join().unwrap();

    let a_count = *va.lock().unwrap();
    let b_count = *vb.lock().unwrap();
    println!("DONE a={} b={}", a_count, b_count);
}
```

等等——在闭包块里仍然有 `let a = Arc::clone(&a)`，闭包体内 `a(a, ...)` 仍然会 shadow。必须在 spawn 闭包外使用不同名字，例如 `lock_a` / `lock_b`：

```rust
    let ha = {
        let lock_a = Arc::clone(&a);
        let lock_b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let va = Arc::clone(&va);
        thread::spawn(move || a(lock_a, lock_b, sa, sb, va))
    };
    let hb = {
        let lock_a = Arc::clone(&a);
        let lock_b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let vb = Arc::clone(&vb);
        thread::spawn(move || b(lock_a, lock_b, sa, sb, vb))
    };
```

这才是正确的完整程序：

```rust
use concir_sync::Semaphore;
use std::sync::{Arc, Mutex};
use std::thread;

fn a(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    va: Arc<Mutex<u32>>,
) {
    let p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    p_sa.release();
    let _p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    *va.lock().unwrap() = 1;
}

fn b(
    a: Arc<Mutex<()>>,
    b: Arc<Mutex<()>>,
    sa: Arc<concir_sync::Semaphore>,
    sb: Arc<concir_sync::Semaphore>,
    vb: Arc<Mutex<u32>>,
) {
    let p_sb = sb.acquire();
    let _gb = b.lock().unwrap();
    p_sb.release();
    let _p_sa = sa.acquire();
    let _ga = a.lock().unwrap();
    *vb.lock().unwrap() = 1;
}

fn bystander(flag: Arc<Mutex<u64>>) {
    loop {
        if let Ok(mut f) = flag.try_lock() {
            *f = f.wrapping_add(1);
        }
    }
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let sa = Semaphore::new(1);
    let sb = Semaphore::new(1);
    let flag = Arc::new(Mutex::new(0u64));
    let va = Arc::new(Mutex::new(0u32));
    let vb = Arc::new(Mutex::new(0u32));

    let ha = {
        let lock_a = Arc::clone(&a);
        let lock_b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let va = Arc::clone(&va);
        thread::spawn(move || a(lock_a, lock_b, sa, sb, va))
    };
    let hb = {
        let lock_a = Arc::clone(&a);
        let lock_b = Arc::clone(&b);
        let sa = Arc::clone(&sa);
        let sb = Arc::clone(&sb);
        let vb = Arc::clone(&vb);
        thread::spawn(move || b(lock_a, lock_b, sa, sb, vb))
    };
    let _hbyst = {
        let flag = Arc::clone(&flag);
        thread::spawn(move || bystander(flag))
    };

    ha.join().unwrap();
    hb.join().unwrap();

    let a_count = *va.lock().unwrap();
    let b_count = *vb.lock().unwrap();
    println!("DONE a={} b={}", a_count, b_count);
}
```
